context.prefix:
'use client'
import { useRouter, useSearchParams } from 'next/navigation'

interface PaginationProps {
  currentPage: number
  totalPages: number
  baseHref: string
}

export default function Pagination({ currentPage, totalPages, baseHref }: PaginationProps) {

output:
  const router = useRouter()
  const searchParams = useSearchParams()

  // Function to generate the URL for a specific page
  const generatePageUrl = (page: number) => {
    return `${baseHref}?${searchParams.toString()}&page=${page}`
  }

  // Generate the previous page link if it exists
  const prevPageLink = currentPage > 1 ? (
    <button onClick={() => router.push(generatePageUrl(currentPage - 1))}>
      Previous Page
    </button>
  ) : null

  // Generate the next page link if it exists
  const nextPageLink = totalPages > currentPage ? (
    <button onClick={() => router.push(generatePageUrl(currentPage + 1))}>
      Next Page
    </button>
  ) : null

  return (
    <div className="pagination">
      {prevPageLink}
      {nextPageLink}
    </div>
  )
}

