  redis: Redis.fromEnv(),
  limiter: Ratelimit.slidingWindow(5, '1 m'),
})

export async function POST(req: Request) {

output:
  try {
    const body = await req.json()
    const { couponCode } = body

    // Check if the coupon code is valid
    if (!couponCode || !couponCode.includes('COUPON')) {
      return NextResponse.json({ error: 'Invalid coupon code' }, { status: 400 })
    }

    // Check if the user has already redeemed this coupon
    const existingRedemption = await fetch(
      `https://api.upstash.io/ratelimit/${couponCode}`,
      {
        headers: {
          'x-upstash-ratelimit-token': process.env.UPSTASH_RATELIMIT_TOKEN,
        },
      }
    )

    if (existingRedemption.ok) {
      return NextResponse.json({ error: 'Coupon already redeemed' }, { status: 400 })
    }

    // Rate limit the user
    const rateLimitResult = await limiter.limit(couponCode)

    if (!rateLimitResult.success) {
      return NextResponse.json({ error: 'Rate limit exceeded' }, { status: 429 })
    }

    // Simulate redeeming the coupon (replace with actual redemption logic)
    const redeemedCoupon = `COUPON_${couponCode}`

    // Store the redemption in Redis
    await fetch(
      `https://api.upstash.io/ratelimit/${redeemedCoupon}`,
      {
        headers: {
          'x-upstash-ratelimit-token': process.env.UPSTASH_RATELIMIT_TOKEN,
        },
      }
    )

    return NextResponse.json({ message: 'Coupon redeemed successfully' }, { status: 200 })
  } catch (error) {
    console.error(error)
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

