import { useState, useMemo } from 'react'

interface UsePaginationOptions {
  totalItems: number
  pageSize: number
  initialPage?: number
}

export function usePagination({ totalItems, pageSize, initialPage = 1 }: UsePaginationOptions) {

output:
  const [currentPage, setCurrentPage] = useState(initialPage)

  // Calculate the total pages based on the total items and page size
  const totalPages = useMemo(() => Math.ceil(totalItems / pageSize), [totalItems, pageSize])

  // Calculate the start index for the current page
  const startIndex = (currentPage - 1) * pageSize

  // Calculate the end index for the current page
  const endIndex = Math.min(startIndex + pageSize, totalItems)

  return {
    currentPage,
    totalPages,
    startIndex,
    endIndex,
    setCurrentPage,
  }
}

// Example usage:
function App() {
  const { currentPage, totalPages, startIndex, endIndex, setCurrentPage } = usePagination({
    totalItems: 100,
    pageSize: 20,
  })

  return (
    <div>
      <h1>Pagination</h1>
      <p>Current Page: {currentPage}</p>
      <p>Total Pages: {totalPages}</p>
      <p>Start Index: {startIndex}</p>
      <p>End Index: {endIndex}</p>

      {/* Example of changing the page */}
      <button onClick={() => setCurrentPage(currentPage + 1)}>Next Page</button>
    </div>
  )
}

export default App
```

