interface DropdownMenuProps {
  trigger: React.ReactNode
  items: { label: string; onSelect: () => void }[]
}

export default function DropdownMenu({ trigger, items }: DropdownMenuProps) {

output:
  const [isOpen, setIsOpen] = useState(false)
  const menuRef = useRef<HTMLDivElement>(null)

  const handleToggle = () => {
    setIsOpen(!isOpen)
  }

  const handleClickOutside = (event: MouseEvent) => {
    if (!menuRef.current || !menuRef.current.contains(event.target)) {
      setIsOpen(false)
    }
  }

  useEffect(() => {
    document.addEventListener('click', handleClickOutside)

    return () => {
      document.removeEventListener('click', handleClickOutside)
    }
  }, [])

  return (
    <div className="relative">
      {trigger}
      <button
        onClick={handleToggle}
        className={`bg-blue-500 text-white font-bold py-2 px-4 rounded-full ${
          isOpen ? 'border-b border-blue-700' : ''
        }`}
      >
        Toggle Dropdown
      </button>
      {isOpen && (
        <div ref={menuRef} className="absolute top-10 right-0 bg-white shadow-lg rounded-md">
          <ul className="list-disc p-4">
            {items.map((item, index) => (
              <li key={index}>
                <a href="#" onClick={() => item.onSelect()}>
                  {item.label}
                </a>
