// Ok<T> like Rust — T is the success value
export class Ok<T> {
  constructor(public value: T) {}

  // Returns true if this is an Ok variant
  public isOk(): boolean {
    return true;
  }

  // Returns true if this is an Err variant
  public isErr(): boolean {
    return false;
  }
}

// Err<E> like Rust — E is the error value
export class Err<E> {
  constructor(public error: E) {}

  // Returns true if this is an Ok variant
  public isOk(): boolean {
    return false;
  }

  // Returns true if this is an Err variant
  public isErr(): boolean {
    return true;
  }
}

// Helper function to create an Ok result
export const ok = <T>(value: T): Result<T> => new Ok(value);

// Helper function to create an Err result
export const err = <E>(error: E): Result<E> => new Err(error);

