export async function POST(req: Request) {
  const body = await req.text()
  const signature = req.headers.get('x-signature')!

output:
 // Assuming the header is named x-signature

  try {
    // Verify the request using the secret key
    const hmac = crypto.createHmac('sha256', process.env.LEMONSQUEZY_SECRET_KEY!)
    hmac.update(body)
    const expectedSignature = hmac.digest('hex')

    if (expectedSignature === signature) {
      console.log('Request verified successfully')
      return NextResponse.json({ message: 'Request verified' })
    } else {
      console.error('Invalid request signature')
      return NextResponse.status(401).json({ message: 'Invalid request signature' })
    }
  } catch (error) {
    console.error('Error verifying request:', error)
    return NextResponse.status(500).json({ message: 'Internal server error' })
  }
}

